Lemma rw_forget : forall m A cs, rw_cells asegs m A cs -> rw_cells asegs m A [CB (cells_size cs) (cells_bytes cs)].
Proof.
ltac2:(KReplay.run1 (kr_t_I_pcseg ()) [] "h01Ah11Hh22csh31lh41mp;1p;4p;3p;2p;6p;7g0000R0p4p710g000NR1p4p710R2p8p1000lp4p7210P2p8g001Xj10Tg002=j14Tg002[j13Tg003>j15Tg003`j1:Tg004@j42Tg0059j19Tg005Yj31TP0j26TP1j67Tg0066j78Tg0074#0#0#0R1#0#0#0#4#3%41#3#5[g007Yg0087R1#:R0g008oR2f2R3f1R4f0R5C2P2f3R6P3%91R3P4P3P0P4P2f4P6A1135C2X30P5A11431614E7F8W1W2W0W4o"). Qed.

